SELECT 
FROM record_creation_template_set
WHERE workspace_id = #{workspaceId} AND record_type = #{recordType}

SELECT FROM record_creation_template WHERE workspace_id = #{workspaceId} AND record_type = #{recordType}
AND status <> 'archived'
ORDER BY position, id

SELECT 
FROM record_creation_template
WHERE workspace_id = #{workspaceId} AND id = #{templateId}

SELECT 
FROM record_creation_template_version
WHERE workspace_id = #{workspaceId}
  AND template_id = #{templateId}
  AND version_number = #{versionNumber}

SELECT COALESCE(MAX(version_number), 0) + 1
FROM record_creation_template_version
WHERE workspace_id = #{workspaceId} AND template_id = #{templateId}

mapper.update:
UPDATE record_creation_template
SET current_version_id = #{versionId},
    revision = revision + 1,
    updated_by_id = #{actorId},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND id = #{templateId}
  AND revision = #{expectedRevision}

UPDATE record_creation_template
SET status = #{status},
    archived_at = #{archivedAt,jdbcType=TIMESTAMP},
    revision = revision + 1,
    updated_by_id = #{actorId},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND id = #{templateId}
  AND revision = #{expectedRevision}

UPDATE record_creation_template
SET position = #{position},
    updated_by_id = #{actorId},
    updated_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND id = #{templateId}
  AND position <> #{position}

UPDATE record_creation_template_set
SET default_template_id = #{templateId,jdbcType=INTEGER},
    revision = revision + 1,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND record_type = #{recordType}
  AND revision = #{expectedRevision}

UPDATE record_creation_template_set
SET revision = revision + 1,
    updated_at = CURRENT_TIMESTAMP(6)
WHERE workspace_id = #{workspaceId}
  AND record_type = #{recordType}
  AND revision = #{expectedRevision}

UPDATE record_creation_template t
LEFT JOIN record_creation_template_version v
  ON v.workspace_id = t.workspace_id AND v.template_id = t.id
SET t.created_by_id = CASE WHEN t.created_by_id = #{userId} THEN NULL ELSE t.created_by_id END,
    t.updated_by_id = CASE WHEN t.updated_by_id = #{userId} THEN NULL ELSE t.updated_by_id END,
    v.created_by_id = CASE WHEN v.created_by_id = #{userId} THEN NULL ELSE v.created_by_id END
WHERE t.created_by_id = #{userId}
   OR t.updated_by_id = #{userId}
   OR v.created_by_id = #{userId}
